@Reusable_d1039fb03394 BIT,
@ExternalDataSourceID_d1039fb03394 UNIQUEIDENTIFIER,
@IsMaterialized_d1039fb03394 BIT
SET
  @ID_d1039fb03394 = '5DF477D8-D037-4EF7-8A6A-AB3C0FB93B05'
SET
  @Name_d1039fb03394 = N'Journal Entries Held Back By Posting Start Date'
SET
  @CategoryID_d1039fb03394 = '126B4161-E7AF-41F6-88B0-0F1F4D8D0867'
SET
  @UserQuestion_d1039fb03394 = N'Which journal entries are held back from batching because they are dated before their company''s posting start date?'
SET
  @Description_d1039fb03394 = N'Pending journal entries dated before their company''s PostingStartDate, one row per entry line, with company, entry number, effective date, entry type, GL account and debit/credit amount. No batch build, preview or sweep picks these up, so finance reconciles them against what was booked directly in the ERP. Export from the query grid.'
SET
  @SQL_d1039fb03394 = N'-- Journal entries held back by their company''s PostingStartDate.
-- Every batch build, preview and sweep selects Pending, non-summary entries dated on or after the
-- company''s PostingStartDate, so the entries listed here never enter a batch. One row per entry
-- line, so finance can reconcile them by account against what was booked directly in the ERP.
-- An entry with no lines yet still appears once, with the line columns empty.
SELECT
    je.CompanyID,
    je.Company,
    acp.PostingStartDate,
    je.EntryNumber,
    je.EffectiveDate,
    je.EntryType,
    je.Description AS EntryDescription,
    jel.LineNumber,
    ga.Code AS GLAccountCode,
    ga.Name AS GLAccountName,
    jel.DebitAmount,
    jel.CreditAmount,
    jel.Description AS LineDescription,
    je.ID AS JournalEntryID
FROM [__mj_BizAppsAccounting].vwJournalEntries je
INNER JOIN [__mj_BizAppsAccounting].AccountingCompanyProfile acp
    ON acp.ID = je.CompanyID
INNER JOIN [__mj_BizAppsAccounting].JournalEntryType jet
    ON jet.ID = je.EntryTypeID
LEFT JOIN [__mj_BizAppsAccounting].JournalEntryLine jel
    ON jel.JournalEntryID = je.ID
LEFT JOIN [__mj_BizAppsAccounting].GLAccount ga
    ON ga.ID = jel.GLAccountID
WHERE je.Status = N''Pending''
    AND jet.IsJournalEntryBatchSummary = 0
    AND acp.PostingStartDate IS NOT NULL
    AND je.EffectiveDate < acp.PostingStartDate
ORDER BY
    je.Company,
    je.EffectiveDate,
    je.EntryNumber,
    jel.LineNumber;
'
SET
  @TechnicalDescription_d1039fb03394 = N'Reads __mj_BizAppsAccounting.vwJournalEntries joined to AccountingCompanyProfile on CompanyID. Keeps Status = Pending, entry types with IsJournalEntryBatchSummary = 0, and EffectiveDate < PostingStartDate where PostingStartDate is set: the same rows the batch engine''s posting-start clause removes from its candidate filter. LEFT JOINs JournalEntryLine and GLAccount, so an entry with no lines appears once with empty line columns. Ordered by company, effective date, entry number, line number.'
SET
  @Status_d1039fb03394 = N'Approved'
SET
  @QualityRank_d1039fb03394 = 8
SET
  @ExecutionCostRank_d1039fb03394 = 2
SET
  @UsesTemplate_d1039fb03394 = 0
SET
  @AuditQueryRuns_d1039fb03394 = 0
SET
